insert into public.projects (name, slug, project_type, industry, summary, platforms, cover_image_url, service_slugs, featured, sort_order, status, published_at) values
('Cricket FabtasyBuzz','cricket-fabtasybuzz','mobile','Fantasy sports','A fantasy cricket platform where fans build teams, join contests, and follow live match scoring.',array['Cross-platform','Real-time','Payments'],'/images/work/app-1.png',array['mobile-app-development','cross-functional-application'],true,15,'published',now()),
('Guri Houses','guri-houses','mobile','Real estate','Guri Houses is a sleek mobile app that makes property deals simple and transparent. With clear listings, easy booking, and direct owner communication, it delivers a modern, user-friendly experience for buyers and sellers alike.',array['Android','iOS','UI/UX'],'/images/GURI-HOUSES.png',array['mobile-app-development','ux-ui-design'],true,40,'published',now()),
('Quick Savaari','quick-savaari','mobile','Ride booking','Quick Savaari is a fast, reliable ride-booking platform built for convenience. With a simple interface, transparent fare details, and easy booking options, it connects users to affordable cab services in just a few taps.',array['Android','iOS','Maps'],'/images/QUICK-SAWARI.png',array['mobile-app-development','cross-functional-application'],true,50,'published',now()),
('Ramba','ramba','mobile','Fashion & lifestyle','Ramba is a modern clothing and lifestyle shopping app built for simplicity and variety. With intuitive navigation, clear product categories, and highlighted discounts, it offers users a seamless way to browse, discover, and purchase fashion essentials.',array['E-Commerce','Android','iOS'],'/images/ROMBA-MOBILE-SHOPPING-APP.png',array['mobile-app-development','ux-ui-design'],true,60,'published',now()),
('Refult','refult','mobile','Fashion brand','Reflut is an online clothing brand app designed to bring fashion closer to users with a smooth, modern interface and a seamless shopping experience.',array['E-Commerce','Android','UI/UX'],'/images/Refult.png',array['mobile-app-development','ux-ui-design'],true,70,'published',now()),
('Sniper Game','sniper-game','game','Game development','Sniper Game is a focused first-person tactical shooter with immersive long-range combat, realistic weapon mechanics, detailed ballistics and modular environments.',array['Unity','FPS','Game Design'],'/images/sniper-game.png',array['game-development'],true,80,'published',now()),
('Ludo Game','ludo-game','game','Casual gaming','Ludo Game is a vibrant digital adaptation of the classic board game, focused on quick multiplayer matches and competitive play.',array['Multiplayer','Android','iOS'],'/images/LUDO-ZONE.png',array['game-development'],true,90,'published',now())
insert into public.blogs (title, slug, excerpt, content, category, cover_image_url, status, published_at) values
('Why user-centric design is key to app success','why-user-centric-design-is-key-to-app-success','Clean code is not enough. Apps people return to are designed around a real job, a real screen, and a real moment of use.','{"body":"Clean code is not enough. Apps people return to are designed around a real job, a real screen, and a real moment of use."}'::jsonb,'Design','/images/services/ui-design.jpg','published',now()),
('UI trends that still matter for mobile apps','ui-ux-trends-for-mobile-apps','Trends are useful when they make an app clearer. Here is what we keep, and what we skip, when we design for phones.','{"body":"Trends are useful when they make an app clearer. Here is what we keep, and what we skip, when we design for phones."}'::jsonb,'Design','/images/pages/design-desk.jpg','published',now()),
('A practical guide to launching a startup app','startup-app-development-guide','From the first brief to the store listing, this is the order we use so a first version ships before the idea changes.','{"body":"From the first brief to the store listing, this is the order we use so a first version ships before the idea changes."}'::jsonb,'Startups','/images/pages/brainstorm.jpg','published',now()),
('How mobile apps change healthcare, retail, and education','mobile-apps-across-industries','The same phone can book a consult, reorder a product, or finish a lesson. The design has to respect how different those jobs are.','{"body":"The same phone can book a consult, reorder a product, or finish a lesson. The design has to respect how different those jobs are."}'::jsonb,'Industries','/images/industries/healthcare.jpg','published',now()),
('Why your business needs a mobile app','why-your-business-needs-a-mobile-app','A website still matters. An app is for the customer who comes back — booking, tracking, reordering, or paying in a few taps.','{"body":"A website still matters. An app is for the customer who comes back — booking, tracking, reordering, or paying in a few taps."}'::jsonb,'Business','/images/industries/ecommerce.jpg','published',now()),
('What actually drives app development cost','what-app-development-costs','Price follows scope: screens, platforms, accounts, payments, and how polished the first release needs to be.','{"body":"Price follows scope: screens, platforms, accounts, payments, and how polished the first release needs to be."}'::jsonb,'Business','/images/pages/typing.jpg','published',now()),
('When a startup should build cross-platform','cross-platform-apps-for-startups','One Flutter or React Native codebase can reach Android and iOS sooner. It is the right call when speed matters more than a fully native feel.','{"body":"One Flutter or React Native codebase can reach Android and iOS sooner. It is the right call when speed matters more than a fully native feel."}'::jsonb,'Development','/images/services/cross-platform.jpg','published',now()),
('Progressive web apps or native apps','pwa-vs-native-apps','A progressive web app is faster to ship from the browser. A native app is better when you need the stores, notifications, and offline use.','{"body":"A progressive web app is faster to ship from the browser. A native app is better when you need the stores, notifications, and offline use."}'::jsonb,'Development','/images/pages/code.jpg','published',now())
