-- CMS media uploads: public reads, authenticated content staff manage uploads.
values ('cms-media', 'cms-media', true, 6291456, array['image/jpeg','image/png','image/webp','image/gif'])
on conflict (id) do update set public = true, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

create policy "public reads cms media" on storage.objects for select using (bucket_id = 'cms-media');
create policy "content staff upload cms media" on storage.objects for insert to authenticated with check (bucket_id = 'cms-media' and private.can_manage_content());
create policy "content staff update cms media" on storage.objects for update to authenticated using (bucket_id = 'cms-media' and private.can_manage_content()) with check (bucket_id = 'cms-media' and private.can_manage_content());
create policy "content staff delete cms media" on storage.objects for delete to authenticated using (bucket_id = 'cms-media' and private.can_manage_content());

-- Bring all existing public portfolio items under CMS control.
on conflict (slug) do nothing;

-- Existing website articles, now editable in the CMS.
on conflict (slug) do nothing;
